// handlers/scanCookies.js
import {
  getSiteById,
  createScanHistory,
  upsertCookie,
  upsertScripts,
} from '../services/db.js';
import { requestDomainMatchesSite } from '../utils/domainValidate.js';
import {
  categorizeCookie,
  getCookieProvider
} from '../data/cookieDatabase.js';
import {
  loadPublishedCustomCookieRules,
  resolveUserDefinedCookieRule,
  hostHintsFromSiteDomain,
} from '../utils/customCookieRules.js';

function parseCookieFromDocumentCookie(cookieString) {
  // Parse simple "name=value" format from document.cookie
  const parts = cookieString.split(';').map((p) => p.trim());
  const firstPart = parts[0] || '';
  const eqIdx = firstPart.indexOf('=');
  const name = (eqIdx >= 0 ? firstPart.slice(0, eqIdx) : firstPart).trim();
  const value = eqIdx >= 0 ? firstPart.slice(eqIdx + 1) : '';

  const cookie = {
    name,
    value,
    domain: null,
    path: '/',
    expires: null,
    httpOnly: false,
    secure: false,
    sameSite: null,
  };

  // Parse additional attributes if present
  for (let i = 1; i < parts.length; i++) {
    const part = parts[i].toLowerCase();
    if (part.startsWith('domain=')) {
      cookie.domain = parts[i].substring(7).trim();
    } else if (part.startsWith('path=')) {
      cookie.path = parts[i].substring(5).trim();
    } else if (part.startsWith('expires=')) {
      cookie.expires = parts[i].substring(8).trim();
    } else if (part === 'httponly') {
      cookie.httpOnly = true;
    } else if (part === 'secure') {
      cookie.secure = true;
    } else if (part.startsWith('samesite=')) {
      cookie.sameSite = parts[i].substring(9).trim();
    }
  }

  return cookie;
}

export async function handleScanCookies(request, env) {
  const db = env.CONSENT_WEBAPP;

  if (request.method !== 'POST') {
    return Response.json({ success: false, error: 'Method Not Allowed' }, { status: 405 });
  }

  let body;
  try {
    body = await request.json();
  } catch (e) {
    return Response.json({ success: false, error: 'Invalid JSON body' }, { status: 400 });
  }

  const siteId = body?.siteId;
  const cookies = body?.cookies || [];
  const scripts = Array.isArray(body?.scripts) ? body.scripts : [];
  const pageUrl = body?.pageUrl || '';
  const createNewScan = body?.createNewScan === true;

  if (!siteId) {
    return Response.json({ success: false, error: 'siteId is required' }, { status: 400 });
  }

  try {
    // Ensure schema exists
    await db.prepare(`
      CREATE TABLE IF NOT EXISTS ScanHistory (
        id TEXT PRIMARY KEY,
        siteId TEXT NOT NULL,
        scanUrl TEXT,
        scriptsFound INTEGER DEFAULT 0,
        cookiesFound INTEGER DEFAULT 0,
        scanDuration INTEGER,
        scanStatus TEXT DEFAULT 'completed',
        createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (siteId) REFERENCES Site(id) ON DELETE CASCADE
      )
    `).run();

    await db.prepare(`
      CREATE TABLE IF NOT EXISTS Cookie (
        id TEXT PRIMARY KEY,
        siteId TEXT NOT NULL,
        scanHistoryId TEXT,
        name TEXT NOT NULL,
        domain TEXT,
        path TEXT,
        category TEXT NOT NULL,
        provider TEXT,
        description TEXT,
        expires TEXT,
        httpOnly INTEGER DEFAULT 0,
        secure INTEGER DEFAULT 0,
        sameSite TEXT,
        isExpected INTEGER DEFAULT 0,
        source TEXT,
        firstSeenAt DATETIME DEFAULT CURRENT_TIMESTAMP,
        lastSeenAt DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (siteId) REFERENCES Site(id) ON DELETE CASCADE,
        FOREIGN KEY (scanHistoryId) REFERENCES ScanHistory(id) ON DELETE SET NULL
      )
    `).run();

    // Add isExpected and source columns if they don't exist
    try {
      await db.prepare(`ALTER TABLE Cookie ADD COLUMN isExpected INTEGER DEFAULT 0`).run();
    } catch (e) {
      // Column already exists, ignore
    }
    
    try {
      await db.prepare(`ALTER TABLE Cookie ADD COLUMN source TEXT`).run();
    } catch (e) {
      // Column already exists, ignore
    }

    // Get site to verify it exists
    const site = await getSiteById(db, siteId);
    if (!site) {
      return Response.json({ success: false, error: 'Site not found' }, { status: 404 });
    }
    if (!requestDomainMatchesSite(site, request)) {
      return Response.json(
        { success: false, error: 'This script is not valid for this domain. It is licensed for the site it was issued to.', code: 'DOMAIN_MISMATCH' },
        { status: 403 }
      );
    }

    const customRules = await loadPublishedCustomCookieRules(db, siteId);

    // Infer domain from pageUrl if not provided in cookies
    let inferredDomain = null;
    try {
      if (pageUrl) {
        const url = new URL(pageUrl);
        inferredDomain = url.hostname;
      }
    } catch (e) {
      // Invalid URL, ignore
    }

    const siteHints = [
      ...new Set([
        ...hostHintsFromSiteDomain(site?.domain ?? site?.DOMAIN ?? ''),
        ...(inferredDomain ? [inferredDomain] : []),
      ]),
    ];

    // For createNewScan (triggered by "Scan Now"), always create a new scan record.
    // For passive collection, reuse the most recent browser scan within the last hour.
    const newScanHistoryId = `client-${siteId}-${crypto.randomUUID()}`;
    let currentScanHistoryId;

    if (createNewScan) {
      // If there is already a pending puppeteer scan for this site, attach cookies to it
      // instead of creating a duplicate record (puppeteer visits the page and triggers this).
      const pendingScan = await db
        .prepare(`SELECT id FROM ScanHistory WHERE siteId = ?1 AND scanStatus = 'pending' ORDER BY createdAt DESC LIMIT 1`)
        .bind(siteId)
        .first();

      if (pendingScan) {
        // Reuse the pending scan — do not create a new record
        currentScanHistoryId = pendingScan.id;
      } else {
        await createScanHistory(db, {
          id: newScanHistoryId,
          siteId,
          scanUrl: pageUrl || 'browser-scan',
          scriptsFound: scripts.length,
          cookiesFound: cookies.length,
          scanDuration: null,
          scanStatus: 'completed',
        });
        currentScanHistoryId = newScanHistoryId;
      }
      // Clear the pendingScan flag so the script stops triggering full scans
      try {
        await db.prepare('UPDATE Site SET pendingScan = 0, updatedAt = ?1 WHERE id = ?2')
          .bind(new Date().toISOString(), siteId)
          .run();
      } catch (e) {
        console.warn('[ScanCookies] Failed to clear pendingScan flag', e);
      }
    } else {
      // If a browser scan is currently in progress for this site, attach to it
      // instead of creating a duplicate row. This happens because Puppeteer visits
      // the live site, which triggers the ConsentBit embed to fire passively.
      const pendingScan = await db
        .prepare(`SELECT id FROM ScanHistory WHERE siteId = ?1 AND scanStatus = 'pending' ORDER BY createdAt DESC LIMIT 1`)
        .bind(siteId)
        .first();

      if (pendingScan) {
        currentScanHistoryId = pendingScan.id;
      } else {
        const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString();
        // Attach the on-page embed's cookies to a browser/scheduled scan that JUST ran:
        // its 'pending' row may have flipped to 'completed' seconds before this report
        // arrived (a race) — that's what produced a SECOND row for one scheduled scan.
        // Keep the window SHORT and EXCLUDE 'client-detection' rows so an organic
        // visitor's report isn't folded into a scan row; organic reports still merge
        // into a recent 'client-detection' row (1h) via the second clause.
        const thirtySecAgo = new Date(Date.now() - 30 * 1000).toISOString();
        const existingScan = await db
          .prepare("SELECT id FROM ScanHistory WHERE siteId = ?1 AND ((createdAt > ?2 AND scanUrl NOT LIKE '%client-detection%') OR (scanUrl LIKE '%client-detection%' AND createdAt > ?3)) ORDER BY createdAt DESC LIMIT 1")
          .bind(siteId, thirtySecAgo, oneHourAgo)
          .first();

        if (!existingScan) {
          await createScanHistory(db, {
            id: newScanHistoryId,
            siteId,
            scanUrl: pageUrl || 'client-detection',
            scriptsFound: scripts.length,
            cookiesFound: cookies.length,
            scanDuration: null,
            scanStatus: 'completed',
          });
          currentScanHistoryId = newScanHistoryId;
        } else {
          currentScanHistoryId = existingScan.id;
          await db.prepare('UPDATE ScanHistory SET cookiesFound = ?1, scriptsFound = ?2 WHERE id = ?3')
            .bind(cookies.length, scripts.length, currentScanHistoryId)
            .run();
        }
      }
    }

    // Store scripts if provided
    if (scripts.length > 0) {
      try {
        await upsertScripts(db, {
          siteId,
          scripts: scripts.map(url => ({
            url: String(url),
            category: (() => {
              try {
                const h = new URL(String(url)).hostname;
                if (h.includes('google-analytics.com') || h.includes('googletagmanager.com')) return 'analytics';
                if (h.includes('facebook.com') || h.includes('fbcdn.net') || h.includes('doubleclick.net')) return 'marketing';
                if (h.includes('hotjar.com') || h.includes('intercom.io') || h.includes('fullstory.com')) return 'behavioral';
                return 'uncategorized';
              } catch { return 'uncategorized'; }
            })(),
          })),
        });
      } catch (e) {
        console.warn('[ScanCookies] Failed to upsert scripts', e);
      }
    }

    // Ensure ScanHistory has a categories column (added after initial schema)
    try {
      await db.prepare(`ALTER TABLE ScanHistory ADD COLUMN categories TEXT`).run();
    } catch (e) {
      // Column already exists, ignore
    }

    // Process and store cookies
    let storedCount = 0;
    const categorySet = new Set();
    const now = new Date().toISOString();
    for (const cookieData of cookies) {
      try {
        // Parse cookie (handle both object format and string format)
        let parsedCookie;
        if (typeof cookieData === 'string') {
          parsedCookie = parseCookieFromDocumentCookie(cookieData);
        } else {
          parsedCookie = {
            name: cookieData.name || '',
            value: cookieData.value || '',
            domain: cookieData.domain || inferredDomain || null,
            path: cookieData.path || '/',
            expires: cookieData.expires || null,
            httpOnly: cookieData.httpOnly || false,
            secure: cookieData.secure || false,
            sameSite: cookieData.sameSite || null,
          };
        }

        if (!parsedCookie.name) {
          continue; // Skip invalid cookies
        }

        // Categorize cookie (auto + user-defined override)
        const autoProvider = getCookieProvider(parsedCookie.name, parsedCookie.domain);
        const autoCategory = categorizeCookie(parsedCookie.name, parsedCookie.domain, autoProvider);
        const rule = await resolveUserDefinedCookieRule(
          db,
          siteId,
          parsedCookie.name,
          parsedCookie.domain,
          customRules,
          siteHints,
        );
        const provider = String(rule?.provider || autoProvider || '').trim() || null;
        const category = String(rule?.category || autoCategory || 'uncategorized').toLowerCase();
        categorySet.add(category);
        const description = String(rule?.description || '').trim() || null;
        const baseSource =
          typeof cookieData === 'string'
            ? 'document.cookie'
            : String(cookieData?.source || 'document.cookie');
        const source = rule ? `user-rule:${baseSource}` : baseSource;

        const cookiePayload = {
          siteId: siteId,
          scanHistoryId: currentScanHistoryId,
          now,
          cookie: {
            name: parsedCookie.name,
            domain: parsedCookie.domain,
            path: parsedCookie.path,
            category,
            provider,
            description,
            expires: parsedCookie.expires,
            httpOnly: parsedCookie.httpOnly,
            secure: parsedCookie.secure,
            sameSite: parsedCookie.sameSite,
            source,
            isExpected: false,
          },
        };
        // Log every field to find undefined (D1 rejects undefined)
        const flat = {
          siteId: cookiePayload.siteId,
          scanHistoryId: cookiePayload.scanHistoryId,
          now: cookiePayload.now,
          name: cookiePayload.cookie.name,
          domain: cookiePayload.cookie.domain,
          path: cookiePayload.cookie.path,
          category: cookiePayload.cookie.category,
          provider: cookiePayload.cookie.provider,
          description: cookiePayload.cookie.description,
          expires: cookiePayload.cookie.expires,
          httpOnly: cookiePayload.cookie.httpOnly,
          secure: cookiePayload.cookie.secure,
          sameSite: cookiePayload.cookie.sameSite,
        };
        for (const [k, val] of Object.entries(flat)) {
          if (val === undefined) console.error('[ScanCookies] undefined field:', k);
        }
        await upsertCookie(db, cookiePayload);

        storedCount++;
      } catch (error) {
        console.error('[ScanCookies] Failed to store cookie:', error, cookieData);
      }
    }

    // Persist the categories snapshot on the ScanHistory record so they survive future upserts
    if (categorySet.size > 0) {
      try {
        await db.prepare('UPDATE ScanHistory SET categories = ?1 WHERE id = ?2')
          .bind(JSON.stringify([...categorySet].sort()), currentScanHistoryId)
          .run();
      } catch (e) {
        console.warn('[ScanCookies] Failed to update ScanHistory categories:', e);
      }
    }

    return Response.json({
      success: true,
      stored: storedCount,
      scanHistoryId: currentScanHistoryId
    });
  } catch (error) {
    console.error('[ScanCookies] Error:', error);
    return Response.json(
      { success: false, error: error?.message || 'Failed to store cookies' },
      { status: 500 }
    );
  }
}
