/**
 * Serves the floating button logo embedded as base64.
 * Logo file: consent-manager/public/logo.webp
 */
const LOGO_BASE64 = '';

export async function handleEmbedFloatingLogo(env) {
  try {
    const binary = atob(LOGO_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return new Response(bytes, {
      status: 200,
      headers: {
        'Content-Type': 'image/webp',
        'Cache-Control': 'public, max-age=86400, immutable',
        'Access-Control-Allow-Origin': '*',
      },
    });
  } catch (e) {
    // Fallback inline SVG
    const svg =
      '<?xml version="1.0" encoding="UTF-8"?>' +
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40" width="40" height="40">' +
      '<circle cx="20" cy="20" r="18" fill="#007aff"/>' +
      '<circle cx="14" cy="14" r="2.2" fill="#ffffff"/>' +
      '<circle cx="24" cy="18" r="2.5" fill="#ffffff"/>' +
      '<circle cx="17" cy="25" r="2" fill="#ffffff"/>' +
      '</svg>';
    return new Response(svg, {
      status: 200,
      headers: {
        'Content-Type': 'image/svg+xml; charset=utf-8',
        'Cache-Control': 'public, max-age=86400, immutable',
        'Access-Control-Allow-Origin': '*',
      },
    });
  }
}
